import React from "react";
import { Link } from "@tanstack/react-router";
import { HeadlineArticle, MinRead } from "../HeadlineArticle";
import { getArticleImage } from "@/lib/news-data";
import { getNewsTitleStyle } from "@/lib/homepage-config";

export function HeroBottomGrid({ cfg, activeBottomItems }: any) {
  if (!activeBottomItems || !Array.isArray(activeBottomItems) || activeBottomItems.length === 0) {
    return null;
  }

  return (
    <div className="mt-10 border-t border-border pt-6 w-full max-w-full min-w-0 overflow-hidden">
      <h2
        className="mb-6 font-bold uppercase tracking-[0.25em]"
        style={{ color: cfg.heroTopStories.color, fontSize: `${cfg.heroTopStories.fontSize}px` }}
      >
        {cfg.heroTopStories.title}
      </h2>
      <div className="grid gap-6 md:grid-cols-3 w-full max-w-full min-w-0">
        
        {/* Column 1 */}
        <div className="flex flex-col h-full w-full min-w-0">
          {activeBottomItems[0] && (
            <Link
              to="/news/$slug"
              params={{ slug: activeBottomItems[0]?.slug || "sample" }}
              className="group block"
            >
              {activeBottomItems[0].img && (
                <div className="overflow-hidden bg-muted">
                  <img
                    src={activeBottomItems[0].img}
                    alt=""
                    aria-hidden="true"
                    loading="lazy"
                    decoding="async"
                    width={400}
                    height={225}
                    onError={(e) => {
                      const el = e.currentTarget;
                      el.onerror = null;
                      el.src = getArticleImage(undefined, 0);
                    }}
                    className="aspect-[16/9] w-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                </div>
              )}
              <h3
                className="headline mt-4 text-xl news-title-interactive group-hover:underline line-clamp-3"
                style={getNewsTitleStyle(cfg?.heroTopStories)}
              >
                {activeBottomItems[0].title}
              </h3>
              <p className="mt-2 text-sm leading-relaxed text-muted-foreground line-clamp-4 overflow-hidden">
                {activeBottomItems[0].excerpt}
              </p>
              <MinRead
                seed={activeBottomItems[0].title}
                kicker={activeBottomItems[0].kicker}
                author={activeBottomItems[0].author}
                views={activeBottomItems[0].views}
              />
            </Link>
          )}
        </div>

        {/* Column 2 */}
        <div className="flex flex-col h-full w-full min-w-0">
          {activeBottomItems[1] && (
            <Link
              to="/news/$slug"
              params={{ slug: activeBottomItems[1]?.slug || "sample" }}
              className="group block border-t border-border pt-6 md:border-t-0 md:pt-0"
            >
              {activeBottomItems[1].img && (
                <div className="hidden md:block overflow-hidden bg-muted">
                  <img
                    src={activeBottomItems[1].img}
                    alt=""
                    aria-hidden="true"
                    loading="lazy"
                    decoding="async"
                    width={400}
                    height={225}
                    onError={(e) => {
                      const el = e.currentTarget;
                      el.onerror = null;
                      el.src = getArticleImage(undefined, 1);
                    }}
                    className="aspect-[16/9] w-full object-cover transition-transform duration-500 group-hover:scale-105"
                  />
                </div>
              )}
              <h3
                className="headline mt-0 md:mt-4 text-xl news-title-interactive group-hover:underline line-clamp-3"
                style={getNewsTitleStyle(cfg?.heroTopStories)}
              >
                {activeBottomItems[1].title}
              </h3>
              <p className="mt-2 text-sm leading-relaxed text-muted-foreground line-clamp-4 overflow-hidden">
                {activeBottomItems[1].excerpt}
              </p>
              <MinRead
                seed={activeBottomItems[1].title}
                kicker={activeBottomItems[1].kicker}
                author={activeBottomItems[1].author}
                views={activeBottomItems[1].views}
              />
            </Link>
          )}
        </div>

        {/* Column 3 */}
        {activeBottomItems.length > 2 && (
          <div className="divide-y divide-border border-t border-border pt-6 md:border-t-0 md:pt-0 w-full min-w-0">
            {activeBottomItems.slice(2, 5).map((item: any, idx: number) => {
              if (!item) return null;
              return (
                <div
                  key={`${item.title || "item"}-${idx}`}
                  className={idx === 0 ? "pb-5" : idx === 1 ? "py-5" : "pt-5"}
                >
                  <HeadlineArticle item={item} dense sectionStyle={cfg?.heroTopStories} />
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export default HeroBottomGrid;
